// Tokens restants pour la réponse dans la fenêtre de contexte.
// TODO : renvoyer la limite entière ignore que le PROMPT occupe déjà de la
//        place — la fenêtre est partagée prompt + réponse.
export function answerBudget(usage) {
  return usage.limit;
}

